$RootFiles = @(Get-ChildItem -LiteralPath $ImgRoot -File | Where-Object { $ImageExtensions -contains $_.Extension.ToLowerInvariant() })
$Plans = @()

foreach ($file in $RootFiles) {
    $manifestType = ''
    if ($ManifestTypes.ContainsKey($file.Name.ToLowerInvariant())) { $manifestType = $ManifestTypes[$file.Name.ToLowerInvariant()] }
    $decision = Get-TargetFolder $file $manifestType $ReferenceFolders
    $hash = Get-Sha256 $file.FullName
    $target = if ($decision.Folder) { Join-Path (Join-Path $ImgRoot ($decision.Folder -replace '/', '\')) $file.Name } else { '' }
    $mirror = if ($decision.Folder) { Join-Path (Join-Path $WebImgRoot ($decision.Folder -replace '/', '\')) $file.Name } else { '' }
    $status = $decision.Status

    if ($decision.Folder) {
        if ((Test-Path -LiteralPath $target -PathType Leaf) -and (Get-Sha256 $target) -ne $hash) {
            $status = 'conflito-destino-diferente'
        }
        if ((Test-Path -LiteralPath $mirror -PathType Leaf) -and (Get-Sha256 $mirror) -ne $hash) {
            $status = 'conflito-web-public-diferente'
        }
    }

    $Plans += [pscustomobject]@{
        Arquivo = $file.Name
        SHA256 = $hash
        TipoManifesto = $manifestType
        PastaDestino = $decision.Folder
        Regra = $decision.Rule
