foreach ($plan in $Plans) {
    if (-not $plan.PastaDestino -or $plan.Status -like 'pendente-*' -or $plan.Status -like 'conflito-*') {
        $applied += $plan
        continue
    }

    $source = Join-Path $ImgRoot $plan.Arquivo
    $target = $plan.CaminhoDestino
    $mirror = $plan.CaminhoWebPublic
    $targetDir = Split-Path -Parent $target
    $mirrorDir = Split-Path -Parent $mirror

    New-Item -ItemType Directory -Force -Path $targetDir | Out-Null
    New-Item -ItemType Directory -Force -Path $mirrorDir | Out-Null

    if (-not (Test-Path -LiteralPath $target -PathType Leaf)) {
        Move-Item -LiteralPath $source -Destination $target
    }
    elseif ((Get-Sha256 $target) -eq $plan.SHA256) {
        New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null
        $archive = Join-Path $backupRoot $plan.Arquivo
        if (Test-Path -LiteralPath $archive) {
            $stem = [System.IO.Path]::GetFileNameWithoutExtension($plan.Arquivo)
            $ext = [System.IO.Path]::GetExtension($plan.Arquivo)
            $archive = Join-Path $backupRoot ($stem + '-' + $plan.SHA256.Substring(0,8) + $ext)
        }
        Move-Item -LiteralPath $source -Destination $archive
    }

