$Plans = @()

foreach ($file in $RootFiles) {
    $manifestType = ''
    if ($ManifestTypes.ContainsKey($file.Name.ToLowerInvariant())) { $manifestType = $ManifestTypes[$file.Name.ToLowerInvariant()] }
    $decision = Get-TargetFolder $file $manifestType $ReferenceFolders
    $hash = Get-Sha256 $file.FullName
    $target = if ($decision.Folder) { Join-Path (Join-Path $ImgRoot ($decision.Folder -replace '/', '\')) $file.Name } else { '' }
    $mirror = if ($decision.Folder) { Join-Path (Join-Path $WebImgRoot ($decision.Folder -replace '/', '\')) $file.Name } else { '' }
    $status = $decision.Status

    if ($decision.Folder) {
        if ((Test-Path -LiteralPath $target -PathType Leaf) -and (Get-Sha256 $target) -ne $hash) {
            $status = 'conflito-destino-diferente'
        }
        if ((Test-Path -LiteralPath $mirror -PathType Leaf) -and (Get-Sha256 $mirror) -ne $hash) {
            $status = 'conflito-web-public-diferente'
        }
    }

    $Plans += [pscustomobject]@{
        Arquivo = $file.Name
        SHA256 = $hash
        TipoManifesto = $manifestType
        PastaDestino = $decision.Folder
        Regra = $decision.Rule
        CaminhoDestino = $target
        CaminhoWebPublic = $mirror
        Status = $status
        ReferenciasAtualizadas = 0
    }
}

Write-Host "Projeto: $Root"
Write-Host "Imagens encontradas na raiz de assets\img: $($RootFiles.Count)"
Write-Host ''
$Plans | Select-Object Arquivo, PastaDestino, Regra, Status | Format-Table -AutoSize

if (-not $Apply) {
    Write-Host ''
    Write-Host 'Prévia apenas: nenhum arquivo foi movido e nenhum código foi alterado.'
    Write-Host 'Revise a classificação. Para aplicar, execute novamente com -Apply.'
    return
}

$applied = @()
$backupRoot = Join-Path $Root 'assets-importacao\reconciliacao-backup\assets-img-root'
foreach ($plan in $Plans) {
    if (-not $plan.PastaDestino -or $plan.Status -like 'pendente-*' -or $plan.Status -like 'conflito-*') {
        $applied += $plan
        continue
    }

    $source = Join-Path $ImgRoot $plan.Arquivo
    $target = $plan.CaminhoDestino
    $mirror = $plan.CaminhoWebPublic
    $targetDir = Split-Path -Parent $target
    $mirrorDir = Split-Path -Parent $mirror

    New-Item -ItemType Directory -Force -Path $targetDir | Out-Null
    New-Item -ItemType Directory -Force -Path $mirrorDir | Out-Null

    if (-not (Test-Path -LiteralPath $target -PathType Leaf)) {
        Move-Item -LiteralPath $source -Destination $target
    }
    elseif ((Get-Sha256 $target) -eq $plan.SHA256) {
        New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null
        $archive = Join-Path $backupRoot $plan.Arquivo
        if (Test-Path -LiteralPath $archive) {
            $stem = [System.IO.Path]::GetFileNameWithoutExtension($plan.Arquivo)
            $ext = [System.IO.Path]::GetExtension($plan.Arquivo)
            $archive = Join-Path $backupRoot ($stem + '-' + $plan.SHA256.Substring(0,8) + $ext)
        }
        Move-Item -LiteralPath $source -Destination $archive
    }

    if (-not (Test-Path -LiteralPath $mirror -PathType Leaf)) {
        Copy-Item -LiteralPath $target -Destination $mirror
    }

    $applied += $plan
}

# Reescreve somente referências que apontam diretamente para a raiz assets/img.
$changedFiles = @{}
foreach ($plan in $applied) {
    if (-not $plan.PastaDestino -or $plan.Status -like 'pendente-*' -or $plan.Status -like 'conflito-*') { continue }
    $newRelative = (($plan.PastaDestino -replace '\\','/') + '/' + $plan.Arquivo)
    $escapedName = [regex]::Escape($plan.Arquivo)
    $pattern = '(?i)(?<prefix>(?:[\\/])?assets[\\/]img[\\/])' + $escapedName + '(?=$|["''?#\s)<])'
    foreach ($file in $CodeFiles) {
        $text = [System.IO.File]::ReadAllText($file.FullName)
        $updated = [regex]::Replace($text, $pattern, { param($m) $m.Groups['prefix'].Value + $newRelative })
        if ($updated -cne $text) {
            [System.IO.File]::WriteAllText($file.FullName, $updated, [System.Text.UTF8Encoding]::new($false))
            if (-not $changedFiles.ContainsKey($file.FullName)) { $changedFiles[$file.FullName] = 0 }
            $changedFiles[$file.FullName]++
            $plan.ReferenciasAtualizadas++
        }
    }
}

foreach ($plan in $applied) {
    if ($plan.Status -eq 'planejado') { $plan.Status = 'movido-e-referenciado' }
    elseif ($plan.Status -eq 'planejado-revisao-produto') { $plan.Status = 'movido-referenciado-revisar-produto' }
    elseif ($plan.Status -eq 'planejado-revisao-identidade') { $plan.Status = 'movido-referenciado-revisar-identidade' }
}

$applied | Select-Object Arquivo, SHA256, TipoManifesto, PastaDestino, Regra, CaminhoDestino, CaminhoWebPublic, Status, ReferenciasAtualizadas |
