        return @{ Folder = 'produtos'; Rule = 'nome de produto ou classificação do manifesto'; Status = 'planejado-revisao-produto' }
    }

    return @{ Folder = ''; Rule = 'nome e manifesto insuficientes; precisa de revisão'; Status = 'pendente-classificacao' }
}

