) {
        return @{ Folder = 'categorias'; Rule = 'manifesto: categoria'; Status = 'planejado' }
    }
    if ($ManifestType -match '(?i)^fornecedores?) {
        return @{ Folder = 'marcas'; Rule = 'manifesto: fornecedor/marca (revisar identidade)'; Status = 'planejado-revisao-identidade' }
    }
    if ($ManifestType -match '^(?i)produto$|^(?i)sem-fornecedor$' -or
        $lower -match 'avon|mary.?kay|eudora|batom|esmalte|perfume|base-|base_|protetor|shampoo|cabelo|creme|máscara|mascara|sabonete|hidratante|desodorante|oleo|óleo|makeup|cosmet|skin.?care|blush|paleta|delineador|rímel|rimel|maquiagem|body.?splash|renew|power.?stay|fps[0-9]') {
        return @{ Folder = 'produtos'; Rule = 'nome de produto ou classificação do manifesto'; Status = 'planejado-revisao-produto' }
    }

    return @{ Folder = ''; Rule = 'nome e manifesto insuficientes; precisa de revisão'; Status = 'pendente-classificacao' }
}

$ManifestTypes = Get-ManifestTypeMap
$CodeFiles = @(Get-CodeFiles)
$ReferenceFolders = Get-ExistingReferenceFolders $CodeFiles
$RootFiles = @(Get-ChildItem -LiteralPath $ImgRoot -File | Where-Object { $ImageExtensions -contains $_.Extension.ToLowerInvariant() })
$Plans = @()

foreach ($file in $RootFiles) {
    $manifestType = ''
    if ($ManifestTypes.ContainsKey($file.Name.ToLowerInvariant())) { $manifestType = $ManifestTypes[$file.Name.ToLowerInvariant()] }
    $decision = Get-TargetFolder $file $manifestType $ReferenceFolders
    $hash = Get-Sha256 $file.FullName
    $target = if ($decision.Folder) { Join-Path (Join-Path $ImgRoot ($decision.Folder -replace '/', '\')) $file.Name } else { '' }
    $mirror = if ($decision.Folder) { Join-Path (Join-Path $WebImgRoot ($decision.Folder -replace '/', '\')) $file.Name } else { '' }
    $status = $decision.Status

    if ($decision.Folder) {
        if ((Test-Path -LiteralPath $target -PathType Leaf) -and (Get-Sha256 $target) -ne $hash) {
            $status = 'conflito-destino-diferente'
        }
        if ((Test-Path -LiteralPath $mirror -PathType Leaf) -and (Get-Sha256 $mirror) -ne $hash) {
            $status = 'conflito-web-public-diferente'
        }
    }

    $Plans += [pscustomobject]@{
        Arquivo = $file.Name
        SHA256 = $hash
        TipoManifesto = $manifestType
        PastaDestino = $decision.Folder
        Regra = $decision.Rule
        CaminhoDestino = $target
        CaminhoWebPublic = $mirror
        Status = $status
        ReferenciasAtualizadas = 0
    }
}

