Write-Host "Arquivos pendentes/conflitantes: $( @($applied | Where-Object { $_.Status -like 'pendente-*' -or $_.Status -like 'conflito-*' }).Count )"
Write-Host "Arquivos de código atualizados: $($changedFiles.Count)"
Write-Host "Relatório: $ReportPath"
Write-Host 'Nenhuma operação foi feita no Supabase.'
) {
        return @{ Folder = 'marcas'; Rule = 'manifesto: fornecedor/marca (revisar identidade)'; Status = 'planejado-revisao-identidade' }
    }
    if ($ManifestType -match '^(?i)produto$|^(?i)sem-fornecedor$' -or
        $lower -match 'avon|mary.?kay|eudora|batom|esmalte|perfume|base-|base_|protetor|shampoo|cabelo|creme|máscara|mascara|sabonete|hidratante|desodorante|oleo|óleo|makeup|cosmet|skin.?care|blush|paleta|delineador|rímel|rimel|maquiagem|body.?splash|renew|power.?stay|fps[0-9]') {
        return @{ Folder = 'produtos'; Rule = 'nome de produto ou classificação do manifesto'; Status = 'planejado-revisao-produto' }
    }

    return @{ Folder = ''; Rule = 'nome e manifesto insuficientes; precisa de revisão'; Status = 'pendente-classificacao' }
}

