    $newRelative = (($plan.PastaDestino -replace '\\','/') + '/' + $plan.Arquivo)
    $escapedName = [regex]::Escape($plan.Arquivo)
    $pattern = '(?i)(?<prefix>(?:[\\/])?assets[\\/]img[\\/])' + $escapedName + '(?=$|["''?#\s)<])'
    foreach ($file in $CodeFiles) {
        $text = [System.IO.File]::ReadAllText($file.FullName)
        $updated = [regex]::Replace($text, $pattern, { param($m) $m.Groups['prefix'].Value + $newRelative })
        if ($updated -cne $text) {
            [System.IO.File]::WriteAllText($file.FullName, $updated, [System.Text.UTF8Encoding]::new($false))
            if (-not $changedFiles.ContainsKey($file.FullName)) { $changedFiles[$file.FullName] = 0 }
            $changedFiles[$file.FullName]++
            $plan.ReferenciasAtualizadas++
        }
    }
}

foreach ($plan in $applied) {
    if ($plan.Status -eq 'planejado') { $plan.Status = 'movido-e-referenciado' }
    elseif ($plan.Status -eq 'planejado-revisao-produto') { $plan.Status = 'movido-referenciado-revisar-produto' }
    elseif ($plan.Status -eq 'planejado-revisao-identidade') { $plan.Status = 'movido-referenciado-revisar-identidade' }
}

$applied | Select-Object Arquivo, SHA256, TipoManifesto, PastaDestino, Regra, CaminhoDestino, CaminhoWebPublic, Status, ReferenciasAtualizadas |
    Export-Csv -LiteralPath $ReportPath -NoTypeInformation -Encoding UTF8

Write-Host ''
Write-Host "Arquivos movidos/distribuídos: $( @($applied | Where-Object { $_.Status -like 'movido-*' }).Count )"
Write-Host "Arquivos pendentes/conflitantes: $( @($applied | Where-Object { $_.Status -like 'pendente-*' -or $_.Status -like 'conflito-*' }).Count )"
Write-Host "Arquivos de código atualizados: $($changedFiles.Count)"
Write-Host "Relatório: $ReportPath"
Write-Host 'Nenhuma operação foi feita no Supabase.'
